#!/usr/bin/env bash
set -euo pipefail
# Ensure verification compiles with the same settings as deployment.
export FOUNDRY_PROFILE="${FOUNDRY_PROFILE:-default}"
ETHERSCAN_API_KEY="${ETHERSCAN_API_KEY:-${ETHERSCAN_V2_API_KEY:-}}"
if [ -z "$ETHERSCAN_API_KEY" ]; then echo "set ETHERSCAN_API_KEY (or ETHERSCAN_V2_API_KEY)"; exit 1; fi
CHAIN_ID=84532
VERIFIER_URL="${VERIFIER_URL:-https://api.etherscan.io/v2/api?chainid=84532}"

# Foundry uses --chain (docs) but some older builds accepted --chain-id.
CHAIN_FLAG="--chain"
if forge verify-contract --help 2>/dev/null | grep -q -- "--chain-id"; then CHAIN_FLAG="--chain-id"; fi

PROFILE_FLAG=""
if forge verify-contract --help 2>/dev/null | grep -q -- "--compilation-profile"; then PROFILE_FLAG="--compilation-profile default"; fi

forge verify-contract 0x5e9b53C3BC2fEe7088308E06d24092C4B40E05d0 src/adapters/chainlink/ChainlinkV2PlusWrapperAdapter.sol:ChainlinkV2PlusWrapperAdapter $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x0000000000000000000000007a1bac17ccc5b313516c5e16fb24f7659aa5ebed000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0xc904f2B6ae561FB454A8743cF3AbEA550E0E65EF src/core/VRFHub.sol:VRFHub $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x0000000000000000000000005e9b53c3bc2fee7088308e06d24092c4b40e05d0000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x33FC265754b5eAcc1e1dE84C28A3046A0f8a43f0 src/core/PoolRegistry.sol:PoolRegistry $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x3AcA2c08F92c744e486b82E1C942A84dF4fCF965 src/core/SettlementRouter.sol:SettlementRouter $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x00000000000000000000000033fc265754b5eacc1e1de84c28a3046a0f8a43f0
forge verify-contract 0x5bEEB8893Cfbe42D8D719173a094b55fC9FB8b05 src/engines/referral/ReferralRegistry.sol:ReferralRegistry $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x5c1290a823cB166295F019619596cf8e0F48D213 src/engines/referral/DefaultReferralEngine.sol:DefaultReferralEngine $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xbBEAb865DBc467AD46f92Cfec642d0Ba92c0e96D src/core/GameHub.sol:GameHub $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 
forge verify-contract 0x16f5BBc7d62Aa8d1828b807F57d3796712C7E3e9 src/core/Bank.sol:Bank $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 
forge verify-contract 0x71D9E131D5F92c3c18a44fAE058ED789085DD095 src/core/Bank.sol:Bank $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 
forge verify-contract 0x1afF50cECFE4B0c4A1DE7Db961031fc8b57217e1 src/modules/dice/DiceModule.sol:DiceModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0x53e915F73b0a7BEA2C453538E272a2f16Dbf0D71 src/modules/cointoss/CoinTossModule.sol:CoinTossModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0x06b4b2cE86D7e3B20382Bbc7a35ccaEa3952ffCF src/modules/roulette/RouletteModule.sol:RouletteModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xE93D7694890c889443F6770AC9faF092a24A5A3e src/modules/keno/KenoModule.sol:KenoModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0x7E085535861f18eAc18519aF8Ae171Db81Dbb786 src/modules/plinko/PlinkoModule.sol:PlinkoModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xf575Baf851c53803d1b6DC3fFbf668507C4c4769 src/modules/sicbo/SicBoModule.sol:SicBoModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xC2Fedd2FF14495fACF5c810352Fb237F43AE47A5 src/modules/slots/SlotsModule.sol:SlotsModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xad377784ee5CF6474F9f3479793c7D5b040F2003 src/modules/baccarat/BaccaratModule.sol:BaccaratModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
